import { defineMiddleware } from 'astro:middleware';
import { CSP } from './lib/csp.js';
import { SECURITY_HEADERS } from './lib/security-headers.js';

// Applies response-level headers to every response generated by the Astro
// worker. dist/client/_headers (generated post-build by scripts/gen-headers.mjs)
// covers static asset responses served via the Cloudflare ASSETS binding,
// but on-demand routes (every page in this site, plus /blog/rss.xml and
// /api/*) generate their responses through the Worker and bypass _headers
// entirely.
//
// CSP value lives in src/lib/csp.js and the rest of the set in
// src/lib/security-headers.js, so middleware + generator share one source.
// Cache-Control defaults to 1h so the edge cache absorbs traffic while still
// letting the dynamic edition line refresh hourly; routes can override by
// setting the header before middleware runs (e.g. prerendered 404 emits
// max-age=0 from Astro).
//
// The non-CSP security headers apply to EVERY worker response, not just
// HTML. /blog/rss.xml is the reason: it renders on-demand for scheduled
// publishing, so it is no longer served by the ASSETS binding and would
// otherwise inherit no security headers at all. They are applied only when
// absent, so a route that picked a stricter value keeps it — /api/*
// responses from src/lib/server.ts send `Referrer-Policy: no-referrer` and
// `Cache-Control: no-store`, which must not be widened to the defaults.

export const onRequest = defineMiddleware(async (context, next) => {
  const response = await next();
  for (const [name, value] of Object.entries(SECURITY_HEADERS)) {
    if (!response.headers.has(name)) response.headers.set(name, value);
  }
  const contentType = response.headers.get('content-type') ?? '';
  if (contentType.includes('text/html')) {
    response.headers.set('Content-Security-Policy', CSP);
    if (!response.headers.has('Cache-Control')) {
      response.headers.set('Cache-Control', 'public, max-age=3600');
    }
  }
  return response;
});
